	struct hl78xx_gnss_data *data_gnss = data_nmea->gnss->data;
	int modem_encoded_systems;
	gnss_systems_t systems_bitmask = 0;

	if (argc < 2) {
		return;
	}

	modem_encoded_systems = ATOI(argv[1], 0, "gnssconf_enabledsys");

	if (modem_encoded_systems == 1) { /* GPS + GLONASS */
		systems_bitmask = GNSS_SYSTEM_GPS | GNSS_SYSTEM_GLONASS;
	} else if (modem_encoded_systems == 0) { /* GPS only */
		systems_bitmask = GNSS_SYSTEM_GPS;
	} else {
		LOG_WRN("Unknown encoded GNSS systems value: %d, defaulting to GPS",
			modem_encoded_systems);
		systems_bitmask = GNSS_SYSTEM_GPS;
	}

	data_gnss->enabled_systems = systems_bitmask;
	LOG_DBG("Enabled GNSS systems: 0x%02X (modem encoded: %d)", systems_bitmask,
		modem_encoded_systems);
}

